# Restore and replay exact locally tested Castaway's Retreat source (stdlib only).
import base64,gzip,hashlib,runpy
from pathlib import Path
here=Path(__file__).resolve().parent
source=gzip.decompress(base64.b64decode("""""",validate=True))
assert hashlib.sha256(source).hexdigest()=="4c3d67e3ba27fd77fdae0a09fbbe0aa5b1ef22ecc92f046eb7a3a908448ed899"
script=here/"build_retreat.py"
if script.exists() and script.read_bytes()!=source: raise RuntimeError("Preserve manually edited source before replay")
script.write_bytes(source)
runpy.run_path(str(script),run_name="__main__")
assert hashlib.sha256(gzip.decompress((here/"prefab-extension/castaways_retreat.nbt").read_bytes())).hexdigest()=="a285dd32c1eb4660b90b04165447fd195f2f6ed3b706cbe22bcf79d74137e4aa"
